<?php
declare(strict_types=1);
namespace App\BusinessModules\Core\Reporting\Application\Subscriptions;
use App\BusinessModules\Core\Reporting\Application\Contracts\{CreateReportExportAction,CreateReportRunAction,GetReportExportAction,GetReportRunAction}; use App\BusinessModules\Core\Reporting\Domain\Contracts\{InAppReportSubscriptionNotifier,ReportSubscriptionDeliveryDispatcher,ReportSubscriptionDeliveryStore,ReportSubscriptionStore}; use App\BusinessModules\Core\Reporting\Domain\DTO\ReportSubscriptionDelivery; use App\BusinessModules\Core\Reporting\Domain\Enums\{ReportExportStatus,ReportOperation,ReportRunStatus,ReportSubscriptionDeliveryStatus}; use DateTimeImmutable;
final readonly class ReportSubscriptionDeliveryProcessor { public function __construct(private ReportSubscriptionDeliveryStore $deliveries,private ReportSubscriptionStore $subscriptions,private ReportSubscriptionExecutionContextFactory $contexts,private ReportSubscriptionDeliveryDispatcher $dispatcher,private CreateReportRunAction $runs,private GetReportRunAction $getRuns,private CreateReportExportAction $exports,private GetReportExportAction $getExports,private InAppReportSubscriptionNotifier $notifier,private ReportSubscriptionPeriodResolver $periods) {} public function process(string $id):void { [$d,$s]=$this->deliveries->lockWithSubscription($id); if($d->executionExpiresAt<=new DateTimeImmutable()){ if(!in_array($d->status,[ReportSubscriptionDeliveryStatus::NOTIFIED,ReportSubscriptionDeliveryStatus::FAILED,ReportSubscriptionDeliveryStatus::EXPIRED],true)) $this->deliveries->markFailedLocked($d,'REPORT_EXECUTION_EXPIRED');return;} try{$input=$d->executionInput();$ctx=$this->contexts->forSubscription($s,ReportOperation::RUN); if($d->status===ReportSubscriptionDeliveryStatus::SCHEDULED){$this->deliveries->beginAttemptLocked($d);$run=$this->runs->handle($ctx,$input->runData($this->periods->asOf($input,$d->scheduledFor)),$d->runIdempotencyKey());$this->deliveries->attachRunLocked($d,$run->id);$this->dispatcher->dispatch($d->id,0);return;} if($d->status===ReportSubscriptionDeliveryStatus::BUILDING_RUN){$run=$this->getRuns->handle($ctx,(string)$d->runId);if(in_array($run->status,[ReportRunStatus::QUEUED,ReportRunStatus::MATERIALIZING],true)){$this->dispatcher->dispatch($d->id,$this->delay($run->pollAfterMs));return;}if($run->status!==ReportRunStatus::READY){$this->retry($d,'REPORT_RUN_FAILED');return;}$export=$this->exports->handle($ctx,$run->id,$input->exportData(),$d->exportIdempotencyKey());$this->deliveries->attachExportLocked($d,$export->id);$this->dispatcher->dispatch($d->id,0);return;}if($d->status===ReportSubscriptionDeliveryStatus::BUILDING_EXPORT){$export=$this->getExports->handle($ctx,(string)$d->exportId);if(in_array($export->status,[ReportExportStatus::QUEUED,ReportExportStatus::RUNNING,ReportExportStatus::UPLOADING],true)){$this->dispatcher->dispatch($d->id,$this->delay($export->pollAfterMs));return;}if($export->status!==ReportExportStatus::READY){$this->retry($d,'REPORT_EXPORT_FAILED');return;}$this->deliveries->markReadyLocked($d);$this->dispatcher->dispatch($d->id,0);return;}if($d->status===ReportSubscriptionDeliveryStatus::READY){$export=$this->getExports->handle($ctx,(string)$d->exportId);$receipt=$this->notifier->notify($ctx,$s,$d,$export,$d->notificationIdempotencyKey());$this->deliveries->markNotifiedLocked($d,$receipt->id,new \App\BusinessModules\Core\Reporting\Domain\ValueObjects\Sha256Hash($d->notificationIdempotencyKey()->hash));}}catch(\Throwable){$this->retry($d,'REPORT_INTERNAL_ERROR');}} private function delay(?int $ms):int{return (int)ceil(max((int)config('reporting_subscriptions.poll_min_ms'),min((int)config('reporting_subscriptions.poll_max_ms'),$ms??1000))/1000);} private function retry(ReportSubscriptionDelivery $d,string $code):void{if($d->attempt>=(int)config('reporting_subscriptions.max_attempts')){$this->deliveries->markFailedLocked($d,$code);return;}$backoff=config('reporting_subscriptions.backoff_seconds')[$d->attempt]??1800;$this->deliveries->rescheduleRetryLocked($d,(new DateTimeImmutable())->modify('+'.$backoff.' seconds'),$code);} }
